import {METRICS,ALL,byId} from './metrics.js';
import {state,label,fmt,escape as e,valueFor,dataFor,workoutsFor,age} from './state.js';
import {dateKey,bounds} from './model.js';
import {icon} from './icons.js';
export const button=(action,name,glyph,cls='icon-button',attrs='')=>`<button class="${cls}" data-action="${action}" aria-label="${e(name)}" title="${e(name)}" ${attrs}>${glyph?icon(glyph):''}${cls.includes('icon-button')?'':e(name)}</button>`;
export const title=(name,action='')=>`<header class="screenbar">${button('back','Indietro','back')}<h1>${e(name)}</h1>${action}</header>`;
export const field=(name,text,value='',type='number',extra='')=>`<label class="field">${e(text)}<input name="${e(name)}" type="${type}" value="${e(value)}" ${extra}></label>`;
export const duration=n=>n>=60?`${Math.floor(n/60)}h ${Math.round(n%60)}m`:`${fmt(n)} min`;
export function dateLabel(date,short=false){return new Date(date+'T12:00:00').toLocaleDateString(state.preferences.language==='en'?'en-GB':'it-IT',short?{day:'numeric',month:'short'}:{weekday:'short',day:'numeric',month:'short'});}
export function period(ctx,detail=false){const[start,end]=bounds(ctx.anchor,ctx.range),canNext=start<bounds(dateKey(),ctx.range)[0];const names={day:'Giorno',week:'Settimana',month:'Mese',year:'Anno'};const text=ctx.range==='day'?dateLabel(ctx.anchor):ctx.range==='year'?ctx.anchor.slice(0,4):ctx.range==='month'?new Date(ctx.anchor+'T12:00:00').toLocaleDateString('it-IT',{month:'long',year:'numeric'}):`${dateLabel(start,true)} – ${dateLabel(end,true)}`;
 const segments=detail?`<div class="screen-content" style="padding-bottom:0"><div class="segmented">${Object.entries(names).map(([key,name])=>`<button data-action="range" data-value="${key}" class="${ctx.range===key?'active':''}" aria-pressed="${ctx.range===key}">${name}</button>`).join('')}</div></div>`:`<select id="range" class="period-type" aria-label="Periodo">${Object.entries(names).map(([key,name])=>`<option value="${key}" ${ctx.range===key?'selected':''}>${name}</option>`).join('')}</select>`;
 return segments+`<section class="date-row"><button data-action="calendar" class="date-label" aria-label="Scegli data"><strong>${e(text)}</strong><small>${ctx.range==='day'?new Date(ctx.anchor+'T12:00:00').toLocaleDateString('it-IT',{day:'numeric',month:'long',year:'numeric'}):names[ctx.range]}</small></button><div class="date-arrows">${button('previous','Periodo precedente','previous')}${button('next','Periodo successivo','next','icon-button',canNext?'':'disabled')}</div></section>`;
}
const goalFor=m=>state.layout.goals[m.id]??m.goal??100;
export function display(m,v){if(m.id==='SLEEP'&&v!==null)return duration(v*60);return `${fmt(v)}${v===null?'':m.unit?' '+m.unit:''}`;}
function pathArc(cx,cy,r,start,sweep){const a=start*Math.PI/180,b=(start+sweep)*Math.PI/180;return `M${cx+r*Math.cos(a)},${cy+r*Math.sin(a)} A${r},${r} 0 ${Math.abs(sweep)>180?1:0} ${sweep>=0?1:0} ${cx+r*Math.cos(b)},${cy+r*Math.sin(b)}`;}
export function hero(ids,ctx){const chosen=ids.slice(0,3).map(byId).filter(Boolean);const rings=chosen.map((m,i)=>{const v=m.max?valueFor(m,ctx.anchor,ctx.range):null,goal=goalFor(m),frac=Math.min(1,Math.max(0,(v??0)/goal));return{m,v,frac,i};});
 const arcs=rings.map(({m,frac,i})=>{const r=i?92:72,start=i===1?130:i===2?50:-90,sweep=i===1?100:i===2?-100:359.99;const p=pathArc(200,100,r,start,sweep);return `<path d="${p}" stroke="${m.color??'#006E8F'}" opacity=".22" stroke-width="${i?10:14}"/><path d="${p}" stroke="${m.color??'#006E8F'}" stroke-width="${i?10:14}" pathLength="100" stroke-dasharray="${frac*100} 100"/>`;}).join('');
 const lbl=i=>{const r=rings[i];return r?`<button class="hero-label ${i===0?'center':''}" style="--accent:${r.m.color??'#006E8F'}" data-action="metric" data-id="${r.m.id}" aria-label="${e(label(r.m))}: ${e(display(r.m,r.v))}"><strong>${r.m.id==='OPENWATCH'?'—':e(r.m.id==='STEPS'?fmt(r.v):display(r.m,r.v))}</strong><small>${e(label(r.m))}</small></button>`:'<span></span>';};
 return `<div class="hero"><svg viewBox="0 0 400 200" class="rings" fill="none" stroke-linecap="round" aria-hidden="true">${arcs}</svg>${lbl(1)}${lbl(0)}${lbl(2)}</div>`;
}
export function tile(m,ctx,editing=false){const v=m.max?valueFor(m,ctx.anchor,ctx.range):null,size=state.layout.sizes[m.id]??2;const content=m.id==='OPENWATCH'?'Nessun orologio':m.id==='MEDICAL_RECORDS'?'Sfoglia':v===null?'Nessun dato':display(m,v);const details=state.layout.details[m.id]??1;const note=details>1&&m.max?(m.mode==='mean'?'Media del periodo':m.mode==='last'?'Ultima misura':'Totale del periodo'):'';const percent=Math.min(100,(v??0)/goalFor(m)*100);
 return `<button class="tile ${size===1?'small':size===4?'large':''}" style="--accent:${m.color??'#006E8F'}" data-action="${editing?'tile-options':'metric'}" data-id="${m.id}"><span class="icon-circle">${icon(m.icon)}</span><span class="tile-copy"><span class="tile-title">${e(label(m))}</span><strong class="tile-value">${e(content)}</strong>${note?`<small>${note}</small>`:''}${details>2&&m.max?`<small>Obiettivo ${fmt(goalFor(m))} ${e(m.unit)}</small>`:''}</span>${m.max?`<span class="tile-meter"><span style="width:${percent}%"></span></span>`:''}</button>`;
}
export function workoutCard(w){return `<button class="activity-card" data-action="activity" data-id="${e(w.id)}"><span class="activity-top">${icon('run')}<strong>Allenamento</strong><span class="chip">Inserimento manuale</span></span><span class="activity-name">${e(w.type)}</span><strong class="activity-duration">${duration(w.duration)}</strong><span class="activity-meta"><span>${e(dateLabel(w.date))} ${e(w.time??'')}</span><span>${w.distance===undefined?'':fmt(w.distance)+' km'}</span><span>${w.calories===undefined?'':fmt(w.calories)+' kcal'}</span></span></button>`;}
export function dashboard(ctx){const order=state.layout.order,top=order.slice(0,3),rest=order.slice(3),paged=state.preferences.paged;
 let grid;
 if(ctx.editing){grid=`<div class="screen-content"><label class="row"><span>Pagine con sei riquadri</span><input type="checkbox" id="paged" ${paged?'checked':''}></label></div><div class="tile-area"><div class="tile-grid">${order.map((id,index)=>{const m=byId(id),size=state.layout.sizes[id]??2;return `<article class="edit-card ${size===1?'small':size===4?'large':''}" draggable="true" data-drag-id="${id}"><div class="controls"><span>${index<3?['Centro','Sinistra','Destra'][index]:size===1?'1×1':size===4?'2×2':'2×1'}</span><span><button data-action="move-up" data-id="${id}" aria-label="Sposta prima" ${index===0?'disabled':''}>↑</button><button data-action="move-down" data-id="${id}" aria-label="Sposta dopo" ${index===order.length-1?'disabled':''}>↓</button><button data-action="remove-tile" data-id="${id}" aria-label="Rimuovi ${e(label(m))}">${icon('close')}</button></span></div>${tile(m,ctx,true)}</article>`;}).join('')}</div><h2 class="group-title">Aggiungi riquadri</h2><div class="tray">${ALL.filter(m=>!order.includes(m.id)).map(m=>`<button data-action="add-tile" data-id="${m.id}">+ ${e(label(m))}</button>`).join('')}</div></div>`;}
 else if(paged){const pages=[];for(let i=0;i<rest.length;i+=6)pages.push(rest.slice(i,i+6));grid=`<div class="tile-area"><div class="carousel" id="carousel">${pages.map(ids=>`<div class="tile-grid">${ids.map(id=>tile(byId(id),ctx)).join('')}</div>`).join('')}</div><div class="page-dots">${pages.map((_,i)=>`<button data-action="page" data-index="${i}" class="${i===ctx.page?'active':''}" aria-label="Pagina ${i+1}"></button>`).join('')}</div></div>`;}
 else grid=`<div class="tile-area"><div class="tile-grid">${rest.map(id=>tile(byId(id),ctx)).join('')}</div></div>`;
 return `<header class="appbar"><div class="brand"><img src="./logo.png" alt=""><strong>OpenVitals</strong></div><button class="icon-button brand-action" data-action="profile" aria-label="Profilo">${state.profile.photo?`<img class="profile-mini" alt="Profilo" src="${e(state.profile.photo)}">`:icon('profile')}</button>${button('achievements','Traguardi','award','icon-button brand-action')}${button('settings','Impostazioni','settings','icon-button brand-action')}</header>${period(ctx)}${ctx.editing?'':hero(top,ctx)}<div class="actions">${button('start','Start workout','run','filled')}${button('log','Log','plus','tonal')}${button('edit',ctx.editing?'Termina modifica':'Modifica dashboard',ctx.editing?'check':'edit')}</div>${grid}<div class="section-header"><h2>Attività</h2>${button('activities','Tutte le attività','next')}</div><div class="activity-list">${workoutsFor(ctx.anchor,ctx.range).length?workoutsFor(ctx.anchor,ctx.range).map(workoutCard).join(''):'<div class="empty-card">Nessuna attività in questo periodo.</div>'}</div><p class="footer-note">Dati demo locali · PWA</p>`;
}
export function chart(m,records){const values=records.filter(r=>Number.isFinite(r[m.key]));if(!values.length)return '<p class="empty">Nessun dato per il periodo selezionato.</p>';const max=Math.max(1,...values.map(r=>r[m.key]));const w=600/Math.max(7,values.length),bars=values.map((r,i)=>{const h=Math.max(2,r[m.key]/max*150);return `<rect x="${i*w+4}" y="${164-h}" width="${Math.max(2,w-8)}" height="${h}" rx="3" fill="${m.color}"><title>${e(dateLabel(r.date))}: ${fmt(r[m.key])} ${e(m.unit)}</title></rect>`;}).join('');return `<svg viewBox="0 0 600 180" role="img" aria-label="Grafico ${e(label(m))}"><path d="M0 14H600M0 89H600M0 164H600" stroke="currentColor" opacity=".12"/>${['Corpo','Parametri vitali','Sonno e recupero'].includes(m.group)?`<polyline points="${values.map((r,i)=>`${i*w+w/2},${164-r[m.key]/max*150}`).join(' ')}" fill="none" stroke="${m.color}" stroke-width="3" stroke-linejoin="round"/>${values.map((r,i)=>`<circle cx="${i*w+w/2}" cy="${164-r[m.key]/max*150}" r="4" fill="${m.color}"><title>${e(dateLabel(r.date))}: ${fmt(r[m.key])}</title></circle>`).join('')}`:bars}</svg><div class="chart-labels"><span>${e(dateLabel(values[0].date,true))}</span><span>${fmt(max)} ${e(m.unit)}</span><span>${e(dateLabel(values.at(-1).date,true))}</span></div>`;}
export function metricScreen(m,ctx){const records=dataFor(ctx.anchor,ctx.range),values=records.filter(r=>Number.isFinite(r[m.key])).map(r=>r[m.key]),v=valueFor(m,ctx.anchor,ctx.range);return title(label(m),button('entry','Aggiungi','plus','icon-button',`data-id="${m.id}"`))+period(ctx,true)+`<div class="screen-content"><section class="detail-total" style="--accent:${m.color}"><strong>${e(display(m,v))}</strong><small>${m.mode==='mean'?'Media del periodo':m.mode==='last'?'Ultimo valore nel periodo':'Totale del periodo'}</small></section><section class="chart-wrap"><h2>${e(label(m))}</h2>${chart(m,records)}</section><div class="stat-grid"><div class="stat"><small>Minimo</small><strong>${fmt(values.length?Math.min(...values):null)}</strong></div><div class="stat"><small>Massimo</small><strong>${fmt(values.length?Math.max(...values):null)}</strong></div></div><h2 class="group-title">Registrazioni</h2><div class="list-card">${records.filter(r=>r[m.key]!==undefined).reverse().map(r=>`<button class="row" data-action="entry" data-id="${m.id}" data-date="${r.date}"><span><strong>${e(dateLabel(r.date))}</strong><small>Inserimento manuale</small></span><b class="row-value">${e(display(m,r[m.key]))}</b>${icon('next')}</button>`).join('')||'<p class="empty">Nessuna registrazione.</p>'}</div>${button('entry','Aggiungi registrazione','plus','filled',`data-id="${m.id}"`)}</div>`;}
export const settingsRows=[['display','Aspetto','Tema, lingua e layout','settings'],['activities-settings','Attività','Obiettivi di attività','run'],['body-profile','Profilo corporeo','Foto, nome, età e dati del corpo','profile'],['nutrition','Alimentazione','Obiettivi di idratazione e macronutrienti','food'],['vitals','Parametri vitali','Misure e storico','heart'],['recovery','Recupero','Sonno, energia e mindfulness','bed'],['cycle','Ciclo','Registrazione manuale','calendar'],['backup','Backup delle impostazioni','Importa ed esporta dati e preferenze','download'],['devices','Dispositivi','Informazioni sulle funzioni della PWA','watch'],['install','Installa OpenVitals','Aggiungi alla schermata Home e usa offline','download'],['about','Informazioni','Versione PWA, codice sorgente e privacy','info']];
export function settings(){return title('Impostazioni')+`<div class="screen-content"><div class="list-card">${settingsRows.map(([id,name,summary,glyph])=>`<button class="row" data-action="navigate" data-route="${id}">${icon(glyph)}<span><strong>${name}</strong><small>${summary}</small></span>${icon('next')}</button>`).join('')}</div></div>`;}
export function log(){return title('Log')+`<div class="screen-content">${[...new Set(METRICS.map(m=>m.group))].map(group=>`<h2 class="group-title">${group}</h2><div class="log-grid">${METRICS.filter(m=>m.group===group).map(m=>`<button class="log-button" style="--accent:${m.color}" data-action="entry" data-id="${m.id}">${icon(m.icon)}<span>${e(label(m))}</span></button>`).join('')}</div>`).join('')}<h2 class="group-title">Allenamenti</h2>${button('workout-entry','Aggiungi attività','plus','tonal')}</div>`;}
export function profile(){return title('Profilo corporeo')+`<div class="screen-content"><form id="profile-form" class="form"><div class="card"><button class="photo-button" type="button" data-action="photo" aria-label="Foto profilo">${state.profile.photo?`<img class="photo" src="${e(state.profile.photo)}" alt="Foto profilo">`:icon('profile')}</button><div class="form">${field('name','Nome',state.profile.name,'text','maxlength="100"')}${field('age','Età',age(),'text','readonly')}${field('birth','Data di nascita',state.profile.birth,'date',`max="${dateKey()}" min="1900-01-01"`)}<label class="field">Sesso<select name="sex"><option value="">Non specificato</option>${['Maschio','Femmina','Altro'].map(v=>`<option ${state.profile.sex===v?'selected':''}>${v}</option>`).join('')}</select></label>${field('height','Altezza (cm)',state.profile.height,'number','min="0" max="300" step="0.1"')}</div></div><p class="error" id="form-error" role="alert"></p><button class="filled">Salva</button></form></div>`;}
export function activityDetail(w){const stats=[['Durata',duration(w.duration)],['Distanza',w.distance===undefined?'—':fmt(w.distance)+' km'],['Calorie attive',w.calories===undefined?'—':fmt(w.calories)+' kcal'],['Frequenza cardiaca',w.heart===undefined?'—':fmt(w.heart)+' bpm'],['Dislivello',w.elevation===undefined?'—':fmt(w.elevation)+' m'],['Passo medio',w.distance?duration(w.duration/w.distance)+'/km':'—']];return title(w.type,button('workout-entry','Modifica attività','edit','icon-button',`data-id="${e(w.id)}"`))+`<div class="screen-content"><p class="privacy-note">${e(dateLabel(w.date))} · ${e(w.time??'')} · Inserimento manuale</p><div class="stat-grid">${stats.map(([k,v])=>`<div class="stat"><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><div class="card" style="margin-top:16px"><h2 class="group-title">Percorso</h2><p class="empty">Questa attività manuale non contiene un tracciato GPS.</p></div>${button('delete-workout','Elimina attività','trash','text-button danger',`data-id="${e(w.id)}"`)}</div>`;}
